const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

let p = 0;
const xi = data[p++], yi = data[p++], xf = data[p++], yf = data[p++];
const n = data[p++];

const rects = [];
const xs = [xi, xf];
const ys = [yi, yf];

for (let i = 0; i < n; i++) {
  const x1 = data[p++], y1 = data[p++], x2 = data[p++], y2 = data[p++];
  rects.push([x1, y1, x2, y2]);
  xs.push(x1, x2);
  ys.push(y1, y2);
}

if (n === 0) {
  console.log(Math.abs(xf - xi) + Math.abs(yf - yi));
  process.exit(0);
}

xs.sort((a, b) => a - b);
ys.sort((a, b) => a - b);

const ux = [];
const uy = [];
for (const v of xs) if (ux.length === 0 || ux[ux.length - 1] !== v) ux.push(v);
for (const v of ys) if (uy.length === 0 || uy[uy.length - 1] !== v) uy.push(v);

const xIndex = new Map();
const yIndex = new Map();
for (let i = 0; i < ux.length; i++) xIndex.set(ux[i], i);
for (let i = 0; i < uy.length; i++) yIndex.set(uy[i], i);

const nx = ux.length;
const ny = uy.length;
const cw = nx - 1;
const ch = ny - 1;

const hStride = cw + 1;
const vStride = nx + 1;
const horizontal = new Int32Array((ny + 1) * hStride);
const vertical = new Int32Array((ch + 1) * vStride);

for (const [x1, y1, x2, y2] of rects) {
  const ix1 = xIndex.get(x1), ix2 = xIndex.get(x2);
  const iy1 = yIndex.get(y1), iy2 = yIndex.get(y2);

  if (ix1 < ix2) {
    horizontal[iy1 * hStride + ix1]++;
    horizontal[iy1 * hStride + ix2]--;
    horizontal[(iy2 + 1) * hStride + ix1]--;
    horizontal[(iy2 + 1) * hStride + ix2]++;
  }

  if (iy1 < iy2) {
    vertical[iy1 * vStride + ix1]++;
    vertical[iy1 * vStride + ix2 + 1]--;
    vertical[iy2 * vStride + ix1]--;
    vertical[iy2 * vStride + ix2 + 1]++;
  }
}

for (let y = 0; y < ny; y++) {
  let rowSum = 0;
  const base = y * hStride;
  for (let x = 0; x < cw; x++) {
    const idx = base + x;
    rowSum += horizontal[idx];
    horizontal[idx] = rowSum + (y > 0 ? horizontal[idx - hStride] : 0);
  }
}

for (let y = 0; y < ch; y++) {
  let rowSum = 0;
  const base = y * vStride;
  for (let x = 0; x < nx; x++) {
    const idx = base + x;
    rowSum += vertical[idx];
    vertical[idx] = rowSum + (y > 0 ? vertical[idx - vStride] : 0);
  }
}

const startX = xIndex.get(xi);
const startY = yIndex.get(yi);
const target = yIndex.get(yf) * nx + xIndex.get(xf);
const start = startY * nx + startX;
const totalNodes = nx * ny;
const INF = 0x3fffffff;

const dist = new Int32Array(totalNodes);
dist.fill(INF);
const heap = new Int32Array(totalNodes);
const position = new Int32Array(totalNodes);
position.fill(-1);

let heapSize = 0;

function decreaseKey(v) {
  let i = position[v];
  if (i === -1) {
    i = heapSize++;
    heap[i] = v;
    position[v] = i;
  }
  while (i > 0) {
    const parent = (i - 1) >> 1;
    const u = heap[parent];
    if (dist[u] <= dist[v]) break;
    heap[i] = u;
    position[u] = i;
    i = parent;
  }
  heap[i] = v;
  position[v] = i;
}

dist[start] = 0;
decreaseKey(start);

let answer = 0;

while (heapSize > 0) {
  const u = heap[0];
  const last = heap[--heapSize];
  position[u] = -2;

  if (heapSize > 0) {
    let i = 0;
    while (true) {
      const left = i * 2 + 1;
      if (left >= heapSize) break;
      const right = left + 1;
      let child = left;
      if (right < heapSize && dist[heap[right]] < dist[heap[left]]) child = right;
      if (dist[last] <= dist[heap[child]]) break;
      heap[i] = heap[child];
      position[heap[i]] = i;
      i = child;
    }
    heap[i] = last;
    position[last] = i;
  }

  const du = dist[u];
  if (u === target) {
    answer = du;
    break;
  }

  const y = Math.floor(u / nx);
  const x = u - y * nx;

  if (x > 0) {
    const v = u - 1;
    const covered = horizontal[y * hStride + x - 1] > 0;
    const nd = du + (covered ? 0 : ux[x] - ux[x - 1]);
    if (nd < dist[v] && position[v] !== -2) {
      dist[v] = nd;
      decreaseKey(v);
    }
  }

  if (x + 1 < nx) {
    const v = u + 1;
    const covered = horizontal[y * hStride + x] > 0;
    const nd = du + (covered ? 0 : ux[x + 1] - ux[x]);
    if (nd < dist[v] && position[v] !== -2) {
      dist[v] = nd;
      decreaseKey(v);
    }
  }

  if (y > 0) {
    const v = u - nx;
    const covered = vertical[(y - 1) * vStride + x] > 0;
    const nd = du + (covered ? 0 : uy[y] - uy[y - 1]);
    if (nd < dist[v] && position[v] !== -2) {
      dist[v] = nd;
      decreaseKey(v);
    }
  }

  if (y + 1 < ny) {
    const v = u + nx;
    const covered = vertical[y * vStride + x] > 0;
    const nd = du + (covered ? 0 : uy[y + 1] - uy[y]);
    if (nd < dist[v] && position[v] !== -2) {
      dist[v] = nd;
      decreaseKey(v);
    }
  }
}

